<?php $label = 'Toko'; ?>
<div class="admin-heading"><div><h1><?= $e($title) ?></h1><p>Kelola direktori toko dan rumah makan penjual kuliner khas Riau.</p></div><a class="button button-primary button-small" href="<?= $e($ui->url('shops.create')) ?>"><?= $ui->icon('plus') ?> Tambah <?= $label ?></a></div>
