</tbody></table></div><p class="table-note"><?= count($items) ?> data ditampilkan<?= $ui->options['adminPreview'] ? ' · data referensi/pratinjau, belum terhubung ke penyimpanan' : '' ?>.</p></div>
<?php else: ?>
<div class="empty-state"><span class="empty-icon"><?= $ui->icon('pin') ?></span><h3>Belum ada toko.</h3><p>Tambahkan toko atau rumah makan penjual kuliner khas untuk membantu wisatawan menemukan tempat makan.</p><a class="button button-outline button-small" href="<?= $e($ui->url('shops.create')) ?>">Tambah Toko <?= $ui->icon('plus') ?></a></div>
